"""Condensed canvases for the 25-minute talk; long-version sources stay separate."""
from presentation_common import *
from sections.boundary import ADAPTED_MODE
from hashlib import sha256


class CondensedSection:
    def short_classical(self):
        self.step('Phase-space Langevin dynamics', 'The paper\'s original coarse field and comoving momentum density obey coupled phase-space Langevin equations. Moving-cutoff terms supply correlated boundary noise. The field momentum here is pi, not yet the later canonical total patch momentum P. Source: Grain and Vennin (2017), JCAP 05, 045, arXiv:1703.00447, sections 2.2 and 2.3.')
        self.section(1,'Classical stochastic inflation')
        phase=equation(r'\begin{aligned}\frac{d\phi}{dN}&=\frac{\pi}{Ha^3}+\xi_\phi\\\frac{d\pi}{dN}&=-\frac{a^3m^2}{H}\phi+\xi_\pi\end{aligned}',size=41).move_to([0,.8,0])
        correlation=equation(r'\langle\xi_f(N)\xi_g(N\prime)\rangle=D_{fg}(N)\delta(N-N\prime)',size=30).move_to([0,-1.6,0])
        references=text_line('Grain & Vennin (2017), JCAP 05, 045; arXiv:1703.00447',17,MUTED).move_to([0,-2.65,0])
        self.play(Write(phase),Write(correlation),FadeIn(references));self.hold()
        self.step('The light-field slow-roll limit', 'Only for a light field, small sigma and the overdamped slow-roll attractor does the standard one-real-noise Starobinsky equation follow. Its noise amplitude is H/(2 pi), with E[dW^2]=dN. Sources: Starobinsky (1986), Lect. Notes Phys. 246, 107, DOI 10.1007/3-540-16452-9_6; Vennin and Starobinsky (2015), arXiv:1506.04732, equation (1.1), specialized to V=m^2 phi^2/2 at constant H.')
        self.section(1,'The familiar light-field limit')
        conditions=equation(r'm\ll H,\quad\sigma\ll1,\quad\text{overdamped attractor}',size=32).move_to([0,1.8,0])
        langevin=equation(r'd\phi=-\frac{m^2\phi}{3H^2}dN+\frac{H}{2\pi}dW_N',size=44).move_to([0,.3,0])
        noise=equation(r'\mathbb E[dW_N]=0,\qquad\mathbb E[dW_N^2]=dN',size=32).move_to([0,-1.3,0])
        references=text_line('Starobinsky (1986); Vennin & Starobinsky (2015), arXiv:1506.04732',16,MUTED).move_to([0,-2.55,0])
        self.play(Write(conditions),Write(langevin),Write(noise),FadeIn(references));self.hold()

    def short_collective(self):
        self.step('Average coordinate and total momentum', 'The average coordinate must be paired with total momentum: Q_n=sum q_j/n, P_n=sum p_j. Their commutator is i. These are canonical oscillator coordinates, not particles.')
        self.section(2,'One collective canonical mode')
        oscillators=VGroup(*[self.oscillator(x,BULK,fr'q_{j+1},p_{j+1}') for j,x in enumerate([-4,0,4])])
        sums=equation(r'Q_n=\frac1n\sum_jq_j,\qquad P_n=\sum_jp_j',size=41).move_to([0,1.8,0])
        comm=equation(r'[q_j,p_k]=i\delta_{jk}\quad\Longrightarrow\quad[Q_n,P_n]=i',size=34,color=GREEN).move_to([0,-1.8,0])
        self.play(FadeIn(oscillators),Write(sums),Write(comm));self.hold()
        self.step('Add one fresh oscillator', 'Add the incoming independent oscillator. The retained coordinate is the enlarged average; its conjugate momentum is the enlarged total.')
        self.section(2,'Add a mode and redefine the collective pair')
        inputs=equation(r'(Q_n,P_n)\quad+\quad(q_{n+1},p_{n+1})',size=39).move_to([0,2.05,0])
        output=equation(r'Q_{n+1}=\frac{nQ_n+q_{n+1}}{n+1},\qquad P_{n+1}=P_n+p_{n+1}',size=36).move_to([0,.7,0])
        self.play(Write(inputs),Write(output));self.hold()
        self.step('Keep the complementary canonical pair', 'The complementary output is Qperp=Q_n-q_new, Pperp=(P_n-n p_new)/(n+1). Retaining both outputs makes the redefinition reversible; no mode has yet been traced out.')
        complement=equation(r'Q^\perp_{n+1}=Q_n-q_{n+1},\qquad P^\perp_{n+1}=\frac{P_n-np_{n+1}}{n+1}',size=36,color=SHELL).move_to([0,-.65,0])
        caption=text_line('Both outputs together retain all the input information',25,MIX).move_to([0,-2.1,0])
        self.play(Write(complement),FadeIn(caption));self.hold()
        self.step('A canonical and unitary redefinition', 'The positions transform with A_n and the momenta with its inverse transpose. The joint map is symplectic and has a unitary implementation U_A. The two canonical output factors commute but their joint state can be entangled.')
        self.section(2,'Separate canonical factors can be entangled')
        unitary=equation(r'U_{A_n}\ket{Q_n,q_{n+1}}=\ket{Q_{n+1},Q^\perp_{n+1}},\qquad U_{A_n}^\dagger U_{A_n}=I',size=33).move_to([0,1.5,0])
        comm=equation(r'[Q_{n+1},P_{n+1}]=[Q^\perp_{n+1},P^\perp_{n+1}]=i',size=35).move_to([0,0,0])
        note=text_line('Commuting factors do not imply a factorized state',28,MIX).move_to([0,-1.6,0])
        self.play(Write(unitary),Write(comm),FadeIn(note));self.hold()

    def short_readout(self):
        self.step('Measuring vs discarding the decoupled mode', 'Original figure from paper_v2.tex, Fig. PureStatePOVM. Efficient rank-one readout of the decoupled output selects a pure conditional bulk state when the joint trajectory is pure. The alternative is its partial trace.')
        self.section(2,'Measuring vs discarding the decoupled mode')
        path=ASSET_DIR/'paper_povm.png'
        figure=ImageMobject(str(path)).scale_to_fit_width(12.4).move_to([0,.55,0])
        figure.asset_content_digest=sha256(path.read_bytes()).hexdigest()
        average=equation(r'\sum_rp_r\rho_{+|r}=\rho_+=\operatorname{Tr}_\perp\rho_{\rm joint}',size=34,color=MIX).move_to([0,-2.05,0])
        caption=text_line('A recorded outcome selects a branch; averaging recovers the trace',22,MUTED).move_to([0,-2.83,0])
        self.play(FadeIn(figure),Write(average),FadeIn(caption));self.hold()
        self.step('Fock and position records', 'Fock readout projects onto number states; ideal position readout uses generalized quadrature eigenstates. They are different rank-one readouts of the same complementary mode. Position outcomes have a probability density.')
        self.section(2,'Two possible records of the complementary mode')
        heads=VGroup(text_line('Fock record',29,SHELL).move_to([-3.2,2.15,0]),text_line('Position record',29,GREEN).move_to([3.2,2.15,0]))
        effects=VGroup(equation(r'E_m=\ket m_\perp\bra m',size=35,color=SHELL).move_to([-3.2,1.1,0]),equation(r'E_r=\ket r_\perp\bra r',size=35,color=GREEN).move_to([3.2,1.1,0]))
        conditional=VGroup(equation(r'\psi_m(Q)\propto\int dR\,\varphi_m^*(R)\Psi(Q,R)',size=29,width=5.8).move_to([-3.2,-.2,0]),equation(r'\psi_r(Q)\propto\Psi(Q,r)',size=33).move_to([3.2,-.2,0]))
        self.play(FadeIn(heads),Write(effects),Write(conditional));self.hold()
        self.step('Recorded rank-one outcomes preserve purity', 'With pure joint input and ideal efficient rank-one readout, each recorded branch remains pure. Finite unresolved position bins need not preserve purity. Average over all full histories to recover the master state.')
        purity=equation(r'\operatorname{Tr}\rho_{+|m}^2=\operatorname{Tr}\rho_{+|r}^2=1',size=36).move_to([0,-1.6,0])
        caveat=text_line('Pure joint input; ideal recorded readout',22,MUTED).move_to([0,-2.65,0])
        self.play(Write(purity),FadeIn(caveat));self.hold()

    def short_canonical(self):
        self.step('Canonical coarse-grained field variables', 'A free spectator field on fixed de Sitter. Define the averaged quantum field and total patch momentum using the sharp Fourier window. V_com is the inverse squared norm of the real-space kernel; it is an effective smearing volume, not a literal top-hat volume.')
        self.section(3,'The retained canonical field mode')
        q=equation(r'\hat Q_N=\int\frac{d^3k}{(2\pi)^3}\Theta(k_\sigma-k)\hat\Phi_{\mathbf k}',size=36,color=BULK).move_to([0,1.6,0])
        p=equation(r'\hat P_N=V_{\rm com}\int\frac{d^3k}{(2\pi)^3}\Theta(k_\sigma-k)\hat\Pi_{\mathbf k}',size=36,color=SHELL).move_to([0,.15,0])
        volume=equation(r'V_{\rm com}^{-1}=\int d^3x\,W_N^2,\qquad\Pi=a^3\dot\Phi',size=30).move_to([0,-1.3,0])
        self.play(Write(q),Write(p),Write(volume));self.hold()
        self.step('The normalized canonical field algebra', 'The equal-time field commutator gives [Q_N,P_N]=i V_com integral W_N squared=i. The factor V_com makes P a total canonical momentum from the outset.')
        comm=equation(r'[\hat Q_N,\hat P_N]=iV_{\rm com}\int d^3x\,W_N^2=i',size=33,color=GREEN).move_to([0,-2.55,0])
        self.play(Write(comm));self.hold()
        self.step('The homogeneous patch Hamiltonian', 'For the sharp Fourier window, V_com=6 pi squared/k_sigma cubed and V_phys=a cubed V_com=6 pi squared/(sigma cubed H cubed). The leading homogeneous bulk Hamiltonian K evolves in e-fold time. The boundary redefinition is an additional contribution to the effective Hamiltonian.')
        self.section(3,'The bulk field Hamiltonian')
        volume=equation(r'V_{\rm com}=\frac{6\pi^2}{k_\sigma^3},\qquad V_{\rm phys}=a^3V_{\rm com}=\frac{6\pi^2}{\sigma^3H^3}',size=34).move_to([0,1.6,0])
        bulk=equation(r'K_{\rm IR}^{\parallel}=\frac{\hat P_N^2}{2HV_{\rm phys}}+\frac{m^2V_{\rm phys}}{2H}\hat Q_N^2',size=40).move_to([0,-.1,0])
        caption=text_line('Free spectator; fixed background; leading super-Hubble gradients',22,MUTED).move_to([0,-2.1,0])
        self.play(Write(volume),Write(bulk),FadeIn(caption));self.hold()

    def short_kraus_trace(self):
        self.step('The short-time joint state', 'Keep the terms needed through order dN. M0=I-(i K_eff+3 A-dagger A/2)dN and M1=-sqrt(3 dN) A. Display the zero/one-quantum output block of the joint state. Higher sectors do not affect the partial trace through this order.')
        self.section(3,'Trace the output of the short-time quantum map')
        kraus=equation(r'M_0=I-\left(iK_{\rm eff}+\frac32A_N^\dagger A_N\right)dN,\qquad M_1=-\sqrt{3dN}\,A_N',size=30).move_to([0,1.9,0])
        block=Matrix([[r'M_0\rho_NM_0^\dagger',r'M_0\rho_NM_1^\dagger'],[r'M_1\rho_NM_0^\dagger',r'M_1\rho_NM_1^\dagger']],h_buff=4.2,v_buff=1.1,element_to_mobject=lambda s:equation(s,size=29)).move_to([0,.05,0])
        label=text_line('Joint output: vacuum / one-quantum sector',21,MUTED).move_to([0,-1.35,0])
        self.play(Write(kraus),Write(block),FadeIn(label));self.hold()
        self.step('Trace and sum the diagonal blocks', 'The output trace has Tr_perp |r><s|=delta_rs. Off-diagonal output blocks vanish, leaving the sum M0 rho M0-dagger + M1 rho M1-dagger. The operators in the blocks still act on the retained mode.')
        entries=block.get_entries()
        summed=equation(r'\rho_{N+dN}=M_0\rho_NM_0^\dagger+M_1\rho_NM_1^\dagger',size=32,color=GREEN).move_to([0,-2.3,0])
        self.play(entries[1].animate.set_opacity(.15),entries[2].animate.set_opacity(.15),Circumscribe(entries[0],color=GREEN),Circumscribe(entries[3],color=GREEN),Write(summed));self.hold()

    def short_massive(self):
        self.step('Massive spectator drift', 'For a free massive spectator, the GKLS first moments obey the damped oscillator equation. This is an equation for unconditional means, not for sample trajectories or purity.')
        self.section(3,'Mass changes the drift and the quantum state')
        drift=equation(r'\frac{d^2\langle\hat Q\rangle}{dN^2}+3\frac{d\langle\hat Q\rangle}{dN}+\frac{m^2}{H^2}\langle\hat Q\rangle=0',size=39).move_to([0,1.1,0])
        note=text_line('Unconditional mean motion; quantum fluctuations remain',25,MUTED).move_to([0,-.7,0])
        self.play(Write(drift),FadeIn(note));self.hold()
        self.step('Three mass regimes', 'The mean drift eigenvalues are -3/2 plus or minus sqrt(9/4-m squared/H squared). The threshold m=3H/2 separates light overdamped, critical and heavy oscillatory mean motion. The next plots show the actual quantum Wigner density and purity, not these mean curves.')
        eigen=equation(r'\lambda_\pm=-\frac32\pm\sqrt{\frac94-\frac{m^2}{H^2}}',size=37,color=MIX).move_to([0,-1.7,0])
        self.play(Write(eigen));self.hold()
        self.wigner_relaxation()
        self.thank_you()
